module fix_uart_idle_pol(
    input       clk,
    input       rst_n,
    input       load,
    input  [7:0] data,
    output reg   tx,
    output reg   busy
);
    reg [2:0] bitcnt;
    reg [7:0] shreg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tx     <= 1'b0;   // suspect: idle level
            busy   <= 1'b0;
            bitcnt <= 3'd0;
            shreg  <= 8'd0;
        end else if (!busy) begin
            if (load) begin
                shreg  <= data;
                tx     <= 1'b1;   // suspect: start bit level
                busy   <= 1'b1;
                bitcnt <= 3'd0;
            end
        end else begin
            if (bitcnt < 3'd7) begin
                tx     <= shreg[0];
                shreg  <= shreg >> 1;
                bitcnt <= bitcnt + 3'd1;
            end else begin
                tx     <= 1'b0;   // suspect: stop bit level
                busy   <= 1'b0;
            end
        end
    end
endmodule

module fix_fifo_flush_drop(
    input        clk,
    input        rst_n,
    input        wr_en,
    input  [7:0] wdata,
    input        rd_en,
    input        flush,
    output reg [7:0] rdata,
    output reg [2:0] count,
    output       empty
);
    reg [1:0] wr_ptr;
    reg [1:0] rd_ptr;
    reg [7:0] mem[0:3];

    assign empty = (count == 3'd0);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr <= 2'd0;
            rd_ptr <= 2'd0;
            count  <= 3'd0;
            rdata  <= 8'd0;
        end else begin
            // read path: serves a byte when one is queued
            if (rd_en && count != 3'd0) begin
                rdata  <= mem[rd_ptr];
                rd_ptr <= rd_ptr + 2'd1;
            end
            // flush and write path
            if (flush) begin
                wr_ptr <= 2'd0;
                rd_ptr <= 2'd0;
                count  <= 3'd0;
            end else begin
                if (wr_en && count < 3'd4) begin
                    mem[wr_ptr] <= wdata;
                    wr_ptr <= wr_ptr + 2'd1;
                end
                case ({wr_en && count < 3'd4, rd_en && count != 3'd0})
                    2'b10:   count <= count + 3'd1;
                    2'b01:   count <= count - 3'd1;
                    default: count <= count;
                endcase
            end
        end
    end
endmodule

