module fix_grant_hold_4req(
    input       clk,
    input       rst_n,
    input  [3:0] req,
    input       done,
    output reg [3:0] grant,
    output reg       busy
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            grant <= 4'd0;
            busy  <= 1'b0;
        end else begin
            // suspect: priority is re-evaluated on every edge
            if (req[3])      grant <= 4'b1000;
            else if (req[2]) grant <= 4'b0100;
            else if (req[1]) grant <= 4'b0010;
            else if (req[0]) grant <= 4'b0001;
            else             grant <= 4'd0;
            busy <= (req != 4'd0);
        end
    end
endmodule

