module fix_af_flag_reg(
    input       clk,
    input       rst_n,
    input       wr_en,
    input       rd_en,
    output reg [3:0] count,
    output      af
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 4'd0;
        end else begin
            case ({wr_en && count < 4'd8, rd_en && count != 4'd0})
                2'b10:   count <= count + 4'd1;
                2'b01:   count <= count - 4'd1;
                default: count <= count;
            endcase
        end
    end

    // suspect: the specification says the flag is registered, not level-sensitive
    assign af = (count >= 4'd6);
endmodule

