module fix_timer_reload_gap(
    input       clk,
    input       rst_n,
    input       load,
    input [7:0] reload_val,
    input       run,
    output reg  tick,
    output reg [7:0] cnt
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt  <= 8'd0;
            tick <= 1'b0;
        end else if (load) begin
            cnt  <= reload_val;
            tick <= 1'b0;
        end else if (run) begin
            if (cnt == 8'd1) begin
                tick <= 1'b1;
                cnt  <= 8'd0;          // suspect: parks at zero
            end else if (cnt == 8'd0) begin
                cnt  <= reload_val;    // suspect: reload one cycle late
                tick <= 1'b0;
            end else begin
                cnt  <= cnt - 8'd1;
                tick <= 1'b0;
            end
        end else begin
            tick <= 1'b0;
        end
    end
endmodule

