module fix_crc4_init(
    input       clk,
    input       rst_n,
    input       ld,
    input  [7:0] d,
    output reg [3:0] crc,
    output reg       vld
);
    function [3:0] crc4_byte;
        input [3:0] seed;
        input [7:0] byte_val;
        reg [3:0] r;
        reg fb;
        integer i;
        begin
            r = seed;
            for (i = 0; i < 8; i = i + 1) begin
                fb = r[3] ^ byte_val[i];
                r  = {r[2:0], 1'b0} ^ (fb ? 4'b0011 : 4'b0000);
            end
            crc4_byte = r;
        end
    endfunction

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            crc <= 4'd0;
            vld <= 1'b0;
        end else begin
            vld <= 1'b0;
            if (ld) begin
                crc <= crc4_byte(4'b1111, d);   // suspect: wrong seed
                vld <= 1'b1;
            end
        end
    end
endmodule

