module fix_vr_deadlock(
    input        clk,
    input        rst_n,
    input        go,
    input  [7:0] payload,
    input        ready,
    output reg   valid,
    output reg [7:0] data,
    output reg   sent
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid <= 1'b0;
            data  <= 8'd0;
            sent  <= 1'b0;
        end else begin
            sent  <= 1'b0;
            if (!valid) begin
                if (go) begin
                    valid <= 1'b1;
                    data  <= payload;
                end
            end else if (ready) begin
                valid <= 1'b0;
                sent  <= 1'b1;
            end else begin
                valid <= go;   // suspect: the offer must not follow go
            end
        end
    end
endmodule

module fix_stack_ptr_wrap(
    input       clk,
    input       rst_n,
    input       push,
    input  [7:0] din,
    input       pop,
    output reg [7:0] dout,
    output reg [3:0] sp,
    output      full,
    output      empty
);
    reg [7:0] mem[0:7];

    assign full  = (sp == 4'd8);
    assign empty = (sp == 4'd0);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sp   <= 4'd0;
            dout <= 8'd0;
        end else if (push) begin
            if (sp < 4'd8) begin
                mem[sp[2:0]] <= din;
            end
            sp <= sp + 4'd1;   // suspect: wraps past the depth
        end else if (pop && sp != 4'd0) begin
            dout <= mem[sp[2:0] - 4'd1];
            sp   <= sp - 4'd1;
        end
    end
endmodule

